return ['domain'=>'zinn-offload','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ta_IN','project-id-version'=>'zinn-offload','pot-creation-date'=>'2026-09-08T21:12:46+00:00','po-revision-date'=>'2026-09-08T21:12:46+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Media Offload'=>'Zinn® Media Offload','https://zinndigital.com/wordpress-plugins/zinn-offload'=>'https://zinndigital.com/wordpress-plugins/zinn-offload','Moves this site\'s media library to Zinn® object storage and serves it from a CDN. Configured from your Zinn® dashboard — no access key is ever typed into WordPress.'=>'இந்தத் தளத்தின் மீடியா நூலகத்தை Zinn® ஆப்ஜெக்ட் ஸ்டோரேஜaக்கு நகர்த்தி, அதை ஒரு CDN-இலிருந்து வழங்குகிறது. உங்கள் Zinn® டாஷ்போர்டிலிருந்து இது கட்டமைக்கப்படுகிறது — வேர்ட்பிரஸில் (WordPress) எந்த அணுகல் விசையும் (access key) தட்டச்சு செய்யப்படுவதில்லை.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'சேமிக்கப்பட்டது. அதை மாற்ற புதிய மதிப்பை உள்ளிடவும்.','Filter this list…'=>'இந்த பட்டியலை வடிகட்டவும்…','Filter this list'=>'இந்த பட்டியலை வடிகட்டவும்','Nothing matches that filter.'=>'அந்த வடிகட்டியுடன் எதுவும் பொருந்தவில்லை.','Add a row'=>'வரி ஒன்றைச் சேர்','Remove this row'=>'இந்த வரியை அகற்று','Remove'=>'நீக்கு','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — கண்ணோட்டம்','Overview'=>'கண்ணோட்டம்','Every Zinn® plugin on this site, and whether it is working.'=>'இந்தத் தளத்தில் உள்ள ஒவ்வொரு Zinn® செருகுநிரலும், அது இயங்குகிறதா இல்லையா என்பதும்.','No connection is needed for this plugin.'=>'இந்த செருகுநிரலுக்கு எந்த இணைப்பும் தேவையில்லை.','Open settings'=>'அமைப்புகளைத் திறக்கவும்','You do not have permission to change these settings.'=>'இந்த அமைப்புகளை மாற்ற உங்களுக்கு அனுமதி இல்லை.','Settings sections'=>'அமைப்புப் பிரிவுகள்','Support'=>'ஆதரவு','Save changes'=>'மாற்றங்களைச் சேமிக்கவும்','Tools'=>'கருவிகள்','Export settings'=>'அமைப்புகளை ஏற்றுமதி செய்','Reset to defaults'=>'இயல்புநிலைகளுக்கு மீட்டமைக்கவும்','This puts every setting on this plugin back to its default. Continue?'=>'இந்த செருகுநிரலின் ஒவ்வொரு அமைப்பையும் அதன் இயல்புநிலைக்கு மாற்றுகிறது. தொடர வேண்டுமா?','Diagnostics for support'=>'ஆதரவுக்கான கண்டறிதல்கள்','Import a settings file'=>'அமைப்புகள் கோப்பை இறக்குமதி செய்','Import'=>'இறக்குமதி செய்','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'ஏற்றுமதி செய்யப்பட்ட கோப்புகளில் கடவுச்சொற்கள், டோக்கன்கள் அல்லது ஏபிஐ விசைகள் (API keys) எப்போதுமே இருக்காது — புதிய தளத்தில் அவற்றை நீங்கள் மீண்டும் உள்ளிட வேண்டும்.','Settings saved.'=>'அமைப்புகள் சேமிக்கப்பட்டன.','Every setting on this plugin is back to its default.'=>'இந்த செருகுநிரலில் உள்ள ஒவ்வொரு அமைப்பும் அதன் இயல்புநிலைக்குத் திரும்பியுள்ளது.','Done.'=>'முடிந்தது.','That action is not available.'=>'அந்தச் செயல் கிடைக்கவில்லை.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'அந்தக் கோப்பைப் படிக்க முடியவில்லை. Zinn® செருகுநிரலில் இருந்து ஏற்றுமதி செய்யப்பட்ட அமைப்புக் கோப்பைத் தேர்ந்தெடுக்கவும்.','That file is too large to be a settings export.'=>'அந்தக் கோப்பு அமைப்புகளின் ஏற்றுமதிக்கு மிகவும் பெரியது.','That file is not a Zinn® settings export.'=>'அந்தக் கோப்பு ஒரு Zinn® அமைப்புகளின் ஏற்றுமதி அல்ல.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'அந்தக் கோப்பு வேறு செருகுநிரலிலிருந்து (%s) ஏற்றுமதி செய்யப்பட்டது, எனவே அதை இங்கே இறக்குமதி செய்வது இந்தச் செருகுநிரலுக்குப் புரியாத அமைப்புகளைச் சேமிக்கும்.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d அமைப்பு இறக்குமதி செய்யப்பட்டது. கடவுச்சொற்களும் API விசைகளும் ஒருபோதும் ஏற்றுமதியில் இருக்காது, எனவே அவற்றை மீண்டும் உள்ளிடவும்.' . "\0" . '%d அமைப்புகள் இறக்குமதி செய்யப்பட்டன. கடவுச்சொற்களும் API சாவிகளும் ஒருபோதும் ஏற்றுமதியில் இருக்காது, எனவே அவற்றை மீண்டும் உள்ளிடவும்.','Zinn Digital® did not return a token. Nothing has been changed on this site.'=>'Zinn Digital® டோக்கனை வழங்கவில்லை. இந்தத் தளத்தில் எதுவும் மாற்றப்படவில்லை.','This site is no longer connected to Zinn® media offload. New uploads will stay on this server. Pair it again from your Zinn Digital® dashboard.'=>'இந்தத் தளம் இனி Zinn® மீடியா ஆஃப்லோடுடன் இணைக்கப்படவில்லை. புதிய பதிவேற்றங்கள் இந்தச் சேவையகத்தில Zinn Digital® டாஷ்போர்டிலிருந்து இதை மீண்டும் இணைக்கவும்.','Zinn Digital® answered with HTTP %d.'=>'Zinn Digital® HTTP %d உடன் பதிலளித்தது.','Disconnected by Zinn Digital®.'=>'Zinn Digital® இலிருந்து துண்டிக்கப்பட்டது.','Connected'=>'இணைக்கப்பட்டுள்ளது','Connecting…'=>'இணைக்கிறது…','Connected, but something needs attention'=>'இணைக்கப்பட்டுள்ளது, ஆனால் எதையோ கவனிக்க வேண்டும்','Not connected'=>'இணைக்கப்படவில்லை','Running on your own account'=>'உங்கள் சொந்த கணக்கில் இயங்குகிறது','We could not check this'=>'இதைச் சரிபார்க்க முடியவில்லை','This plugin did not say why. Send a diagnostics report and we will look.'=>'இந்த செருகுநிறைக்கான காரணம் தெரிவிக்கப்படவில்லை. கண்டறிதல் அறிக்கையை அனுப்பவும், நாங்கள் பரிசீலிக்கிறோம்.','Connection status'=>'இணைப்பு நிலை','Last checked %s ago.'=>'கடைசியாக %s முன்பு சரிபார்க்கப்பட்டது.','(opens in a new tab)'=>'(புதிய தாவலில் திறக்கும்)','Send this to Zinn® support'=>'இதனை Zinn® ஆதரவுப் பகுதிக்கு அனுப்பவும்','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'இதுதான் சரியாக அனுப்பப்படும் — வேறு எதுவும் இல்லை, மறைக்கப்பட்டதும் இல்லை. உங்கள் கடவுச்சொற்கள், டோக்கன்கள் மற்றும் API விசைகள் இதில் இல்லை.','The diagnostics report that will be sent'=>'அனுப்பப்படவுள்ள கண்டறிதல் அறிக்கை','Copy to clipboard'=>'கிளிப் போர்டுக்கு நகலெடு','Send this report to Zinn® support'=>'இந்த அறிக்கையை Zinn® ஆதரவுக் குழுவிற்கு அனுப்பவும்','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'நாங்கள் உங்களுக்காக ஒரு ஆதரவுச் சீட்டைத் திறந்து, மின்னஞ்சல் மூலம் பதிலளிப்போம். இதை அனுப்ப விரும்பவில்லை எனில், மேலே உள்ளதை நகலெடுத்து நீங்களே ஒரு சீட்டில் ஒட்டவும்.','Copied'=>'நகலெடுக்கப்பட்டது','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'இந்தச் சேவையகத்திலிருந்து (%s) Zinn Digital®-ஐ எங்களால் அடைய முடியவில்லை. மேலே உள்ள அறிக்கையை நகலெடுத்து அதற்குப் பதிலாக ஒரு டிக்கைத் திறக்கவும் — உங்கள் அமைப்புகளில் எதுவும் தவறில்லை.','Sent. Zinn® support has your report and will reply by email.'=>'Zinn® ஆதரவு உங்கள் அறிக்கையைப் பெற்றுள்ளது, மேலும் மின்னஞ்சல் மூலம் பதிலளிக்கும்.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'உங்கள் Zinn® ஆதரவுப் பிரிவு உங்கள் அறிக்கையைப் பெற்றுள்ளது — குறிப்பு %s — மேலும் மின்னஞ்சல் மூலம் பதிலளிக்கும்.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'நீங்கள் குறுகிய காலத்தில் பல அறிக்கைகளை அனுப்பியுள்ளீர்கள். சில நிமிடங்கள் காத்திருந்து மீண்டும் முயற்சிக்கவும் — முந்தையவை வந்து சேர்ந்துவிட்டன.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® தற்சமயம் அறிக்கையை ஏற்றுக்கொள்ள முடியவில்லை — இது உங்கள் தரப்புப் பிழை அல்ல, எங்கள் தரப்புப் பிழை. சிறிது நேரத்திற்குப் பிறகு மீண்டும் முயற்சிக்கவும் அல்லது மேலே உள்ள அறிக்கையை ஒரு டிக்கெட்டில் நகலெடுக்கவும்.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'அறிக்கை மறுக்கப்பட்டது (HTTP %d). அதை மேலே நகலெடுத்து, அந்த எண்ணைக் குறிப்பிட்டு ஒரு டிக்கெட்டைத் திறக்கவும்.','%s — guides and services'=>'%s — வழிகாட்டிகளும் சேவைகளும்','User guides'=>'பயனர் வழிகாட்டிகள்','Read the %s user guide'=>'%s பயனர் வழிகாட்டியைப் படிக்கவும்','Hide this'=>'ம_ மறைக்கவும்','Zinn® hosting for WordPress'=>'WordPress-க்கான Zinn® ஹோஸ்டிங்','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, தினசரி காப்புப்பிரதிகள், இலவச இடம்பெயர்வு மற்றும் ஒன்றுக்கும் மேற்பட்ட தளங்களை இயக்குபவர்களுக்காக உருவாக்கப்பட்ட கட்டுப்பாட்டுப் பலகம்.','The Zinn® marketplace'=>'Zinn® அங்காடி','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'நிறுவப்பட்ட தளங்கள், டொமைன்கள் மற்றும் இணைப்பு இடங்களை வாங்கவும் விற்கவும், இரு தரப்பினரும் திருப்தி அடையும் வரை பணம் பாதுகாப்பாகப் பிடிக்கப்படும்.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — இதைத் தொழிலாகச் செய்பவர்களை அமர்த்துங்கள்','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'எங்கள் உலகளாவிய ப்ரீலான்ஸ் சந்தை: எழுத்தாளர்கள், வடிவமைப்பாளர்கள், டெவலப்பர்கள் மற்றும் எஸ்சிஓ நிபுணர்களிடமிருந்து 10,000-க்கும் மேற்பட்ட ஆயத்த சேவைகளை உலாவுங்கள், அல்லது ஒரு திட்டத்தைப் பதிவிட்டு அவர்களை ஏலம் எடுக்க அனுமதிக்கவும்.','Media Offload'=>'மீடியா ஆஃப்லோடு','Connection'=>'இணைப்பு','What gets moved'=>'எது நகர்த்தப்படுகிறது','How media is served'=>'ஊடகங்கள் எவ்வாறு வழங்கப்படுகின்றன','Move a batch now'=>'ஒரு தொகுதியை இப்போதே நகர்த்து','Media already moved is never affected by a change here — its address does not change.'=>'இங்கு செய்யப்படும் மாற்றத்தால் ஏற்கனவே நகர்த்தப்பட்ட மீடியா எந்த வகையிலும் பாதிக்கப்படாது — அதன் முகவரி மாறாது.','New uploads'=>'புதிய பதிவேற்றங்கள்','Move new uploads to Zinn® storage as they arrive'=>'புதிய பதிவேற்றங்களை Zinn® சேமிப்பகத்திற்கு அவை வந்தவுடன் நகர்த்தவும்','Existing media'=>'தற்போதைய ஊடகம்','Keep moving the media library that is already here'=>'இங்கே ஏற்கனவே உள்ள மீடியா நூலகத்தை நகர்த்துவதைத் தொடரவும்','A few files an hour, in the background, picking up where it left off. Turning this off pauses it; nothing already moved comes back.'=>'ஒரு மணி நேரத்திற்கு சில கோப்புகள், பின்னணியில், அது விட்ட இடத்திலிருந்து தொடங்கும். இதை அணைப்பது அதை இடைநிறுத்தும்; ஏற்கனவே நகர்த்தப்பட்ட எதுவும் திரும்ப வராது.','Files per hourly pass'=>'மணிநேர பாஸுக்கான கோப்புகள்','Each attachment is several files and every one is a full upload. Raise this on a fast host with a generous execution limit; lower it if passes are being cut short.'=>'ஒவ்வொரு இணைப்பும் பல கோப்புகளைக் கொண்டுள்ளது மற்றும் ஒவ்வொன்றும் முழுமையான பதிவேற்றமாகும். தாராளமான எக்ஸிகியூஷன் வரம்பைக் கொண்ட வேகமான ஹோஸ்டில் இதை உயர்த்தவும்; பாஸ்கள் குறுக்கப்படுமானால் அதைக் குறைக்கவும.','Leave files smaller than'=>'இதனைவிடச் சிறிய கோப்புகளை விட்டுவிடுங்கள்','Kilobytes. A tiny icon costs more in the extra connection than it saves in disk, so there is rarely a reason to move one. Set to 0 to move everything.'=>'கிலோபைட்டுகள். ஒரு சிறிய ஐகானானது வட்டு இடத்தில் மிச்சப்படுத்துவதைவிட கூடுதல் இணைப்பில் அதிக செலவை ஏற்படுத்துகிறது, எனவே அதை நகர்த்துவதற்கான காரணம் அரிதாகவே உள்ளது. அனைத்தையும் நகர்த்த 0 என அமைக்கவும்.','Never move these types'=>'இந்த வகைகளை ஒருபோதும் நகர்த்த வேண்டாம்','Useful when a plugin reads a file straight off the disk — a font, a PDF a form builder stamps, an audio file a player seeks inside.'=>'ஒரு செருகுநிரல் வட்டில் இருந்து நேரடியாக ஒரு கோப்பைப் படிக்கும் போது பயனுள்ளதாக இருக்கும் — ஒரு எழுத்துரு, ஒரு படிவம் உருவாக்குபவர் முத்திரையிடும் PDF, ஒரு பிளேயர் தேடும் ஆடியோ கோப்பு.','These two are the ones to be careful with — read each description before changing it.'=>'இவை இரண்டும் கவனமாக இருக்க வேண்டியவை — மாற்றுவதற்கு முன் ஒவ்வொரு விளக்கத்தையும் படிக்கவும்.','Serve from Zinn® storage'=>'Zinn® சேமிப்பகத்திலிருந்து வழங்கவும்','Point image and file addresses at Zinn® storage'=>'பட மற்றும் கோப்பு முகவரிகளை Zinn® சேமிப்பகத்திற்கு சுட்டவும்','Off, files are uploaded but still served from this server — which is the safe state while you check everything arrived. On, visitors are served from storage and this server stops carrying the traffic.'=>'முடக்கப்பட்டுள்ளது, கோப்புகள் பதிவேற்றப்பட்டுள்ளன ஆனால் இந்த சேவையகத்திலிருந்தே தொடர்ந்து வழங்கப்படுகின்றன — இதுவே அனைத்தும் சரியாக வந்துசேர்ந்ததா என்பதைச் சரிபார்க்கும் போது பாதுகாப்பான நிலையாகும். இயக்கப்பட்டுள்ளது, பார்வையாளர்களுக்கு சேமிப்பகத்திலிருந்து வழங்கப்படுகிறது மேலும் இந்த சேவையகம் போக்குவரத்தைக் கையாள்வதை நிறுத்துகிறது.','Free the disk space'=>'வட்டு இடத்தைக் காலியாக்கவும்','Delete the local copy once every size has uploaded'=>'ஒவ்வொரு அளவும் பதிவேற்றப்பட்டதும் உள்ளூர் நகலை நீக்கவும்','This is the point of offloading, and it is also the irreversible half. Leave it off until “Serve from Zinn® storage” is on and you have checked your site — a local copy is the only thing that saves you if something was missed.'=>'இதுவே ஆஃப்லோடிங்கின் முக்கிய நோக்கமாகும், மேலும் இது திரும்பப் பெற முடியாத பாதியுமாகும். “Zinn® சேமிப்பகத்திலிருந்து வழங்கவும்” என்பது இயக்கப்படும் வரை மற்றும் நீங்கள் உங்கள் தளத்தை சரிபார்க்கும் வரை இதை முடக்கியே வைக்கவும் — ஏதேனும் விடுபட்டிருந்தால் உள்ளூர் நகல் (local copy) மட்டுமே உங்களைக் காப்பாற்றும்.','Deleting local copies cannot be undone from this screen. Take a backup first — the Zinn® Connector plugin can do that for you.'=>'உள்ளூர் நகல்களை நீக்குவதை இந்தத் திரையிலிருந்து மாற்ற முடியாது. முதலில் காப்புப்பிரதியை எடுங்கள் — Zinn® கனெக்டர் செருகுநிரல் அதை உங்களுக்காகச் செய்ய முடியும்.','This site is not connected to Zinn® storage yet, so there is nowhere to move media to.'=>'இந்த தளம் Zinn® சேமிப்பகத்துடன் இன்னும் இணைக்கப்படவில்லை, எனவே ஊடகங்களை நகர்த்துவதற்கு எ இடமும் இல்லை.','%d attachment moved.'=>'%d இணைப்பு நகர்த்தப்பட்டது.' . "\0" . '%d இணைப்புகள் நகர்த்தப்பட்டன.','This site is not connected to Zinn® storage.'=>'இந்த தளம் Zinn® சேமிப்பகத்துடன் இணைக்கப்படவில்லை.','Nothing is wrong — it has simply not been paired yet. Media stays on this server until it is.'=>'எதுவும் தவறாகவில்லை — அது இன்னும் இணைக்கப்படவில்லை. அதுவரை மீடியா இந்த சர்வரிலேயே இருக்கும்.','Connected, but the last upload failed.'=>'இணைக்கப்பட்டுள்ளது, ஆனால் கடைசி பதிவேற்றம் தோல்வியடைந்தது.','Try a batch now'=>'ஒரு தொகுதி தொகுப்பை இப்போது முயற்சிக்கவும்','Connected. Every attachment has been moved.'=>'இணைக்கப்பட்டது. ஒவ்வொரு இணைப்பும் மாற்றப்பட்டுள்ளது.','Connected. %1$s of %2$s attachments still on this server.'=>'இணைக்கப்பட்டது. %2$s இணைப்புகளில் %1$s இணைப்புகள் இசு சர்வரில் உள்ளன.','Moved so far'=>'இதுவரை நகர்த்தப்பட்டது','%1$s files, %2$s'=>'%1$s கோப்புகள், %2$s','Still on this server'=>'இந்தச் சேவையகத்தில்தான் உள்ளது','%1$s of %2$s attachments'=>'%2$s இணைப்புகளில் %1$s இணைப்புகள்','Served from'=>'இதிலிருந்து வழங்கப்படுகிறது','this server'=>'இந்த சேவையகம்','Connect this site'=>'இந்தத் தளத்தை இணைக்கவும்','Open your Zinn Digital® dashboard, go to Storage → Media offload, and press “Pair a site”. Paste the code below.'=>'உங்கள் Zinn Digital® டாஷ்போர்டைத் திறந்து, சேமிப்பகம் (Storage) → மீடியா ஆஃப்லோட் (Media offload) பகுதிக்குச் சென்று, “Pair a site” என்பதை அழுத்தவும். கீழே உள்ள குறியீட்டை ஒட்டவும்.','Pairing code'=>'இணைப்புக் குறியீடு','Disconnect this site'=>'இந்த தளத்தைத் துண்டிக்குக','New uploads will stay on this server. Media already moved keeps working — its address does not change.'=>'புதிய பதிவேற்றங்கள் இந்த சேவையகத்திலேயே இருக்கும். ஏற்கனவே நகர்த்தப்பட்ட மீடியா தொடர்ந்து செயல்படும் — அதன் முகவரி மாறாது.','You do not have permission to manage this site.'=>'இந்தத் தளத்தை நிர்வகிக்க உங்களுக்கு அனுமதி இல்லை.','Paste the pairing code from your Zinn Digital® dashboard.'=>'உங்கள் Zinn Digital® டாஷ்போர்டிலிருந்து இணைப்புக் குறியீட்டை ஒட்டவும்.','Connected. New uploads will be stored with Zinn Digital® from now on, and your existing media will move in the background.'=>'இணைக்கப்பட்டுள்ளது. இனிமேல் புதிய பதிவேற்றங்கள் Zinn Digital® இல் சேமிக்கப்படும், மேலும் உங்கள் தற்போதைய மீடியா பின்னணியில் நகரும்.','Disconnected. Media already moved keeps working; new uploads stay on this server.'=>'துண்டிக்கப்பட்டது. ஏற்கனவே நகர்த்தப்பட்ட மீடியா தொடர்ந்து செயல்படும்; புதிய பதிவேற்றங்கள் இந்த சேவையகத்திலேயே இருக்கும்.','That file could not be read from this server, so nothing was uploaded.'=>'அந்தக் கோப்பைப் இந்தச் சேவையகத்திலிருந்து படிக்க முடியவில்லை, எனவே எதுவும் பதிவேற்றப்படவில்லை.','This site could not stream the upload, so nothing was sent.'=>'இந்தத் தளம் பதிவேற்றத்தை ஸ்ட்ரீம் செய்ய முடியவில்லை, எனவே எதுவும் அனுப்பப்படவில்லை.','This file is %1$s and this site\'s PHP has no cURL, so the largest it can upload is %2$s.'=>'இந்தக் கோப்பு %1$s ஆகும், மேலும் இந்தத் தளத்தின் PHP-ல் cURL இல்லை, எனவே இதனால் பதிவேற்றக்கூடிய அதிகபட்ச அளவு %2$s ஆகும்.','The upload could not be completed.'=>'பதிவேற்றத்தை முடிக்க முடியவில்லை.','Storage refused the upload (HTTP %d).'=>'சேமிப்பிடம் பதிவேற்றத்தை மறுத்துவிட்டது (HTTP %d).','Style preset'=>'பாணி முன்கட்டமைப்பு','A starting point. Anything below overrides it.'=>'ஒரு தொடக்க புள்ளி. கீழே உள்ள எதும் அதை விட மேலானது.','Use my own colours and sizes'=>'எனது சொந்த நிறங்களையும் அளவுகளையும் பயன்படுத்துங்கள்','Leave this off and the preset is used exactly as it is.'=>'இதை அணைத்து வைக்கவும், மேலும் முன்னமைவு அப்படியே பயன்படுத்தப்படும்.','See the Zinn Digital® release notes.'=>'Zinn Digital® வெளியீட்டு குறிப்புகளைப் பார்க்கவும்.','The downloaded update failed its integrity check and was not installed.'=>'பதிவிறக்கம் செய்யப்பட்ட புதுப்பிப்பு அதன் ஒருமைமைச் சோதனையில் தோல்வியுற்றது மற்றும் நிறுவப்படவில்லை.']];